def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    import os
    import sys

    if sys.platform == "win32" and cmd:
        script = cmd[0]
        shebang = None

        if os.path.isfile(script):
            with open(script, 'r', encoding='utf-8') as f:
                first_line = f.readline().strip()
                if first_line.startswith('#!'):
                    shebang = first_line[2:].strip()

        if shebang:
            shebang_parts = shebang.split()
            interpreter = shebang_parts[0]
            interpreter_args = shebang_parts[1:] if len(shebang_parts) > 1 else []
            return (interpreter, *interpreter_args, script, *cmd[1:])

    return cmd

