def _verify(iface, candidate, tentative=False, vtype=None):
    import zope.interface
    import inspect
    import functools

    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not provide the interface {iface}")

    required_methods = set(iface.names(all=True, inherited=False)).difference(set(iface.names(all=False, inherited=True)))
    required_attributes = set(attr for attr in iface.names(all=True, inherited=False) if inspect.isdatadescriptor(getattr(iface, attr)))

    candidate_methods = set(getattr(candidate, name) for name in dir(candidate) if callable(getattr(candidate, name)))
    candidate_attributes = set(getattr(candidate, name) for name in dir(candidate) if not callable(getattr(candidate, name)))

    for method_name in required_methods:
        if not hasattr(candidate, method_name):
            errors.append(f"Required method {method_name} is missing")
            continue
        method = getattr(iface, method_name)
        candidate_method = getattr(candidate, method_name)
        if not callable(candidate_method):
            errors.append(f"Required method {method_name} is not callable")
            continue
        sig = inspect.signature(method)
        candidate_sig = inspect.signature(candidate_method)
        if not sig == candidate_sig:
            errors.append(f"Method {method_name} has an incorrect signature. Expected {sig}, got {candidate_sig}")

    for attr_name in required_attributes:
        if not hasattr(candidate, attr_name):
            errors.append(f"Required attribute {attr_name} is missing")

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid(f"Multiple errors found: {', '.join(errors)}")

    return True

